import binascii
import codecs
for data in (b'x', b'x0', b'0x', b'410x', b'41'):
    try:
        result = binascii.unhexlify(data)
        print(data, result)
    except BaseException as error:
        print(data, type(error).__module__, type(error).__name__, error.args, error.__cause__, error.__context__, error.__suppress_context__, error.__traceback__ is not None)

